-- Habitación Llena · Accesos y llaves electrónicas
create extension if not exists pgcrypto;

create table if not exists public.hotel_access_points(
 id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,room_id bigint references public.habitaciones(id) on delete cascade,name text not null,kind text not null default 'room' check(kind in('room','entrance','elevator','parking','common')),visibility text not null default 'private' check(visibility in('private','public')),zone text,provider text not null default 'PIN',provider_ref text,connection_status text not null default 'not_connected' check(connection_status in('not_connected','configured','connected','error')),pin_enabled boolean not null default true,remote_open_enabled boolean not null default false,linked_service_kind text,active boolean not null default true,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists hotel_access_points_room_unique on public.hotel_access_points(property_id,room_id) where room_id is not null and kind='room';
create index if not exists hotel_access_points_property_active_idx on public.hotel_access_points(property_id,active,kind,name);
create table if not exists public.hotel_access_links(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,source_point_id uuid not null references public.hotel_access_points(id) on delete cascade,inherited_point_id uuid not null references public.hotel_access_points(id) on delete cascade,sequence integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(property_id,source_point_id,inherited_point_id),check(source_point_id<>inherited_point_id));
create index if not exists hotel_access_links_source_idx on public.hotel_access_links(property_id,source_point_id,active,sequence);
create table if not exists public.hotel_access_policies(property_id uuid primary key references public.properties(id) on delete cascade,enabled boolean not null default true,require_full_payment boolean not null default true,require_checkin boolean not null default true,require_room_ready boolean not null default true,require_arrival_time boolean not null default true,allow_assisted_override boolean not null default true,pin_length smallint not null default 4 check(pin_length between 4 and 8),timezone text not null default 'America/Argentina/Buenos_Aires',arrival_lead_minutes integer not null default 0 check(arrival_lead_minutes between 0 and 1440),checkout_grace_minutes integer not null default 0 check(checkout_grace_minutes between 0 and 1440),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.hotel_access_grants(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,reservation_id bigint not null references public.reservas(id) on delete cascade,primary_point_id uuid not null references public.hotel_access_points(id) on delete cascade,pin_code text not null,status text not null default 'prepared' check(status in('prepared','active','revoked','expired')),generation_mode text not null default 'manual' check(generation_mode in('manual','checkin','precheckin','system')),valid_from timestamptz not null,valid_until timestamptz not null,conditions_snapshot jsonb not null default '{}'::jsonb,guest_token_hash bytea,guest_token_created_at timestamptz,created_by uuid references auth.users(id) on delete set null,activated_at timestamptz,revoked_at timestamptz,revoke_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(valid_until>valid_from));
create index if not exists hotel_access_grants_reservation_idx on public.hotel_access_grants(property_id,reservation_id,created_at desc);
create unique index if not exists hotel_access_grants_current_reservation_idx on public.hotel_access_grants(property_id,reservation_id) where status in('prepared','active');
create unique index if not exists hotel_access_grants_active_pin_idx on public.hotel_access_grants(property_id,pin_code) where status in('prepared','active');
create index if not exists hotel_access_grants_guest_token_idx on public.hotel_access_grants(guest_token_hash) where guest_token_hash is not null;
create table if not exists public.hotel_access_events(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,reservation_id bigint references public.reservas(id) on delete set null,grant_id uuid references public.hotel_access_grants(id) on delete set null,access_point_id uuid references public.hotel_access_points(id) on delete set null,event_type text not null,result text not null default 'ok',source text not null default 'pms',actor_id uuid references auth.users(id) on delete set null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists hotel_access_events_property_created_idx on public.hotel_access_events(property_id,created_at desc);create index if not exists hotel_access_events_reservation_idx on public.hotel_access_events(property_id,reservation_id,created_at desc);

alter table public.hotel_access_points enable row level security;alter table public.hotel_access_links enable row level security;alter table public.hotel_access_policies enable row level security;alter table public.hotel_access_grants enable row level security;alter table public.hotel_access_events enable row level security;
revoke all on public.hotel_access_points,public.hotel_access_links,public.hotel_access_policies,public.hotel_access_grants,public.hotel_access_events from anon;
grant select on public.hotel_access_points,public.hotel_access_links,public.hotel_access_policies,public.hotel_access_grants,public.hotel_access_events to authenticated;grant insert,update,delete on public.hotel_access_points,public.hotel_access_links,public.hotel_access_policies to authenticated;

create or replace function private.hl_access_permission(p_property_id uuid,p_permission text) returns boolean language plpgsql stable security definer set search_path='public','private','pg_temp' as $$declare v_role text;v_override boolean;begin if auth.uid() is null then return false;end if;select pm.role into v_role from public.property_members pm where pm.property_id=p_property_id and pm.user_id=auth.uid();if v_role is null then return false;end if;select rp.allowed into v_override from public.hotel_role_permissions rp where rp.property_id=p_property_id and rp.role=v_role and rp.permission=p_permission;if found then return v_override;end if;if v_role='owner' then return true;end if;if p_permission='frontdesk.access.open' then return v_role in('manager','reception','night_audit');end if;if p_permission='hotel.access.manage' then return v_role='manager';end if;return false;end$$;
revoke execute on function private.hl_access_permission(uuid,text) from public,anon;grant execute on function private.hl_access_permission(uuid,text) to authenticated;

drop policy if exists hotel_access_points_select_access on public.hotel_access_points;create policy hotel_access_points_select_access on public.hotel_access_points for select to authenticated using(private.hl_access_permission(property_id,'frontdesk.access.open'));
drop policy if exists hotel_access_points_insert_manage on public.hotel_access_points;create policy hotel_access_points_insert_manage on public.hotel_access_points for insert to authenticated with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_points_update_manage on public.hotel_access_points;create policy hotel_access_points_update_manage on public.hotel_access_points for update to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage')) with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_points_delete_manage on public.hotel_access_points;create policy hotel_access_points_delete_manage on public.hotel_access_points for delete to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_links_select_access on public.hotel_access_links;create policy hotel_access_links_select_access on public.hotel_access_links for select to authenticated using(private.hl_access_permission(property_id,'frontdesk.access.open'));
drop policy if exists hotel_access_links_insert_manage on public.hotel_access_links;create policy hotel_access_links_insert_manage on public.hotel_access_links for insert to authenticated with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_links_update_manage on public.hotel_access_links;create policy hotel_access_links_update_manage on public.hotel_access_links for update to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage')) with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_links_delete_manage on public.hotel_access_links;create policy hotel_access_links_delete_manage on public.hotel_access_links for delete to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_policies_select_access on public.hotel_access_policies;create policy hotel_access_policies_select_access on public.hotel_access_policies for select to authenticated using(private.hl_access_permission(property_id,'frontdesk.access.open'));
drop policy if exists hotel_access_policies_insert_manage on public.hotel_access_policies;create policy hotel_access_policies_insert_manage on public.hotel_access_policies for insert to authenticated with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_policies_update_manage on public.hotel_access_policies;create policy hotel_access_policies_update_manage on public.hotel_access_policies for update to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage')) with check(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_policies_delete_manage on public.hotel_access_policies;create policy hotel_access_policies_delete_manage on public.hotel_access_policies for delete to authenticated using(private.hl_access_permission(property_id,'hotel.access.manage'));
drop policy if exists hotel_access_grants_select_access on public.hotel_access_grants;create policy hotel_access_grants_select_access on public.hotel_access_grants for select to authenticated using(private.hl_access_permission(property_id,'frontdesk.access.open'));
drop policy if exists hotel_access_events_select_access on public.hotel_access_events;create policy hotel_access_events_select_access on public.hotel_access_events for select to authenticated using(private.hl_access_permission(property_id,'frontdesk.access.open'));

insert into public.hotel_access_policies(property_id) select id from public.properties on conflict(property_id) do nothing;
insert into public.hotel_access_points(property_id,room_id,name,kind,visibility,provider,pin_enabled,remote_open_enabled,active) select h.property_id,h.id,'Habitación '||h.nombre,'room','private','PIN',true,false,coalesce(h.activa,true) from public.habitaciones h on conflict(property_id,room_id) where room_id is not null and kind='room' do update set name=excluded.name,active=excluded.active,updated_at=now();
create or replace function private.hl_access_sync_room_point() returns trigger language plpgsql security definer set search_path='public','private','pg_temp' as $$begin insert into public.hotel_access_points(property_id,room_id,name,kind,visibility,provider,pin_enabled,remote_open_enabled,active) values(new.property_id,new.id,'Habitación '||new.nombre,'room','private','PIN',true,false,coalesce(new.activa,true)) on conflict(property_id,room_id) where room_id is not null and kind='room' do update set name=excluded.name,active=excluded.active,updated_at=now();return new;end$$;
drop trigger if exists trg_hl_access_sync_room_point on public.habitaciones;create trigger trg_hl_access_sync_room_point after insert or update of nombre,activa,property_id on public.habitaciones for each row execute function private.hl_access_sync_room_point();

create or replace function private.hl_access_readiness_json(p_reservation_id bigint) returns jsonb language plpgsql stable security definer set search_path='public','private','pg_temp' as $$declare r public.reservas%rowtype;h public.habitaciones%rowtype;pol public.hotel_access_policies%rowtype;v_paid numeric:=0;v_total numeric:=0;v_payment_ok boolean;v_checkin_ok boolean;v_room_ok boolean;v_time_ok boolean;v_arrival timestamptz;v_departure timestamptz;v_in text;v_out text;v_ops jsonb;begin select * into r from public.reservas where id=p_reservation_id;if not found then return jsonb_build_object('exists',false);end if;select * into h from public.habitaciones where id=r.habitacion_id;select * into pol from public.hotel_access_policies where property_id=r.property_id;if not found then pol.property_id:=r.property_id;pol.enabled:=true;pol.require_full_payment:=true;pol.require_checkin:=true;pol.require_room_ready:=true;pol.require_arrival_time:=true;pol.allow_assisted_override:=true;pol.pin_length:=4;pol.timezone:='America/Argentina/Buenos_Aires';pol.arrival_lead_minutes:=0;pol.checkout_grace_minutes:=0;end if;select coalesce(s.operational_settings,'{}'::jsonb) into v_ops from public.hotel_os_settings s where s.property_id=r.property_id;v_in:=coalesce(nullif(r.hora_llegada_estimada,''),nullif(v_ops->>'checkin_time',''),'14:00');v_out:=coalesce(nullif(r.hora_salida_estimada,''),nullif(v_ops->>'checkout_time',''),'10:00');begin v_arrival:=((r.fecha_entrada::text||' '||v_in)::timestamp at time zone pol.timezone)-make_interval(mins=>pol.arrival_lead_minutes);exception when others then v_arrival:=((r.fecha_entrada::text||' 14:00')::timestamp at time zone pol.timezone);end;begin v_departure:=((r.fecha_salida::text||' '||v_out)::timestamp at time zone pol.timezone)+make_interval(mins=>pol.checkout_grace_minutes);exception when others then v_departure:=((r.fecha_salida::text||' 10:00')::timestamp at time zone pol.timezone);end;select coalesce(sum(case when upper(coalesce(p.moneda,'ARS'))=upper(coalesce(r.moneda,'ARS')) then p.monto when upper(coalesce(r.moneda,'ARS'))='ARS' and upper(coalesce(p.moneda,'ARS'))='USD' then p.monto*greatest(coalesce(r.tipo_cambio,1),0.000001) when upper(coalesce(r.moneda,'ARS'))='USD' and upper(coalesce(p.moneda,'ARS'))='ARS' then p.monto/greatest(coalesce(r.tipo_cambio,1),0.000001) else 0 end),0) into v_paid from public.pagos p where p.reserva_id=r.id and p.property_id=r.property_id;v_total:=greatest(coalesce(r.precio_total,0),0);v_payment_ok:=not pol.require_full_payment or v_paid>=v_total-0.01;v_checkin_ok:=not pol.require_checkin or lower(coalesce(r.estado,''))='alojado' or lower(coalesce(r.web_checkin_status,'')) in('submitted','completed','approved','done','verified','complete');v_room_ok:=not pol.require_room_ready or lower(coalesce(h.estado,'')) in('inspeccionada','inspeccion','libre','disponible') or lower(coalesce(r.estado,''))='alojado';v_time_ok:=not pol.require_arrival_time or now()>=v_arrival;return jsonb_build_object('exists',true,'enabled',pol.enabled,'ready',pol.enabled and v_payment_ok and v_checkin_ok and v_room_ok and v_time_ok and now()<v_departure and lower(coalesce(r.estado,'')) not in('cancelada','finalizada') and not coalesce(r.no_show,false),'payment',jsonb_build_object('ok',v_payment_ok,'paid',v_paid,'total',v_total,'required',pol.require_full_payment),'checkin',jsonb_build_object('ok',v_checkin_ok,'status',r.web_checkin_status,'reservation_status',r.estado,'required',pol.require_checkin),'room',jsonb_build_object('ok',v_room_ok,'status',h.estado,'required',pol.require_room_ready),'time',jsonb_build_object('ok',v_time_ok,'valid_from',v_arrival,'valid_until',v_departure,'required',pol.require_arrival_time),'allow_assisted_override',pol.allow_assisted_override);end$$;
revoke execute on function private.hl_access_readiness_json(bigint) from public,anon,authenticated;
create or replace function public.hl_access_readiness(p_reservation_id bigint) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$declare v_property uuid;v_result jsonb;begin select property_id into v_property from public.reservas where id=p_reservation_id;if v_property is null then raise exception using errcode='P0002',message='Reserva inexistente.';end if;if not private.user_has_property_access(v_property) then raise exception using errcode='42501',message='No tenés acceso a esta propiedad.';end if;v_result:=private.hl_access_readiness_json(p_reservation_id);update public.hotel_access_grants g set status=case when(v_result->>'ready')::boolean then 'active' else 'prepared' end,activated_at=case when(v_result->>'ready')::boolean then coalesce(g.activated_at,now()) else g.activated_at end,conditions_snapshot=v_result,updated_at=now() where g.reservation_id=p_reservation_id and g.status in('prepared','active') and now()<g.valid_until;return v_result;end$$;
revoke all on function public.hl_access_readiness(bigint) from public,anon;grant execute on function public.hl_access_readiness(bigint) to authenticated;

create or replace function private.hl_access_make_pin(p_property_id uuid,p_length integer) returns text language plpgsql volatile security definer set search_path='public','private','pg_temp' as $$declare v_pin text;i integer;v_min bigint:=power(10,greatest(4,least(8,p_length))-1)::bigint;v_max bigint:=power(10,greatest(4,least(8,p_length)))::bigint-1;begin for i in 1..30 loop v_pin:=floor(random()*(v_max-v_min+1)+v_min)::bigint::text;if not exists(select 1 from public.hotel_access_grants where property_id=p_property_id and pin_code=v_pin and status in('prepared','active')) then return v_pin;end if;end loop;raise exception using errcode='P0001',message='No pudimos generar un PIN único. Reintentá.';end$$;revoke execute on function private.hl_access_make_pin(uuid,integer) from public,anon,authenticated;
create or replace function private.hl_access_ensure_grant(p_reservation_id bigint,p_mode text,p_actor uuid) returns public.hotel_access_grants language plpgsql security definer set search_path='public','private','pg_temp' as $$declare r public.reservas%rowtype;p public.hotel_access_points%rowtype;pol public.hotel_access_policies%rowtype;g public.hotel_access_grants%rowtype;ready jsonb;v_from timestamptz;v_until timestamptz;v_in text;v_out text;v_ops jsonb;begin select * into r from public.reservas where id=p_reservation_id for update;if not found then raise exception using errcode='P0002',message='Reserva inexistente.';end if;if r.habitacion_id is null then raise exception using errcode='22023',message='La reserva todavía no tiene habitación asignada.';end if;if lower(coalesce(r.estado,'')) in('cancelada','finalizada') or coalesce(r.no_show,false) then raise exception using errcode='22023',message='La reserva ya no puede recibir accesos.';end if;select * into p from public.hotel_access_points where property_id=r.property_id and room_id=r.habitacion_id and kind='room' and active limit 1;if not found then raise exception using errcode='22023',message='La habitación no tiene un acceso activo configurado.';end if;select * into pol from public.hotel_access_policies where property_id=r.property_id;if not found then insert into public.hotel_access_policies(property_id) values(r.property_id) returning * into pol;end if;if not pol.enabled then raise exception using errcode='22023',message='El módulo de accesos está desactivado para esta propiedad.';end if;update public.hotel_access_grants set status='expired',updated_at=now() where property_id=r.property_id and reservation_id=r.id and status in('prepared','active') and valid_until<=now();select * into g from public.hotel_access_grants where property_id=r.property_id and reservation_id=r.id and status in('prepared','active') order by created_at desc limit 1;if found then return g;end if;select coalesce(s.operational_settings,'{}'::jsonb) into v_ops from public.hotel_os_settings s where s.property_id=r.property_id;v_in:=coalesce(nullif(r.hora_llegada_estimada,''),nullif(v_ops->>'checkin_time',''),'14:00');v_out:=coalesce(nullif(r.hora_salida_estimada,''),nullif(v_ops->>'checkout_time',''),'10:00');begin v_from:=((r.fecha_entrada::text||' '||v_in)::timestamp at time zone pol.timezone)-make_interval(mins=>pol.arrival_lead_minutes);exception when others then v_from:=((r.fecha_entrada::text||' 14:00')::timestamp at time zone pol.timezone);end;begin v_until:=((r.fecha_salida::text||' '||v_out)::timestamp at time zone pol.timezone)+make_interval(mins=>pol.checkout_grace_minutes);exception when others then v_until:=((r.fecha_salida::text||' 10:00')::timestamp at time zone pol.timezone);end;ready:=private.hl_access_readiness_json(r.id);insert into public.hotel_access_grants(property_id,reservation_id,primary_point_id,pin_code,status,generation_mode,valid_from,valid_until,conditions_snapshot,created_by,activated_at) values(r.property_id,r.id,p.id,private.hl_access_make_pin(r.property_id,pol.pin_length),case when(ready->>'ready')::boolean then 'active' else 'prepared' end,case when p_mode in('manual','checkin','precheckin','system') then p_mode else 'manual' end,v_from,v_until,ready,p_actor,case when(ready->>'ready')::boolean then now() end) returning * into g;insert into public.hotel_access_events(property_id,reservation_id,grant_id,access_point_id,event_type,result,source,actor_id,details) values(r.property_id,r.id,g.id,p.id,'pin_generated','ok',coalesce(p_mode,'manual'),p_actor,jsonb_build_object('mode',coalesce(p_mode,'manual'),'valid_from',v_from,'valid_until',v_until));return g;end$$;
revoke execute on function private.hl_access_ensure_grant(bigint,text,uuid) from public,anon,authenticated;
create or replace function public.hl_access_generate_grant(p_reservation_id bigint,p_mode text default 'manual') returns public.hotel_access_grants language plpgsql security definer set search_path='public','private','pg_temp' as $$declare v_property uuid;begin select property_id into v_property from public.reservas where id=p_reservation_id;if v_property is null then raise exception using errcode='P0002',message='Reserva inexistente.';end if;if not private.hl_access_permission(v_property,'frontdesk.access.open') then raise exception using errcode='42501',message='Tu rol no puede generar accesos.';end if;return private.hl_access_ensure_grant(p_reservation_id,p_mode,auth.uid());end$$;
revoke all on function public.hl_access_generate_grant(bigint,text) from public,anon;grant execute on function public.hl_access_generate_grant(bigint,text) to authenticated;
create or replace function public.hl_access_revoke_grant(p_grant_id uuid,p_reason text default 'manual') returns public.hotel_access_grants language plpgsql security definer set search_path='public','private','pg_temp' as $$declare g public.hotel_access_grants%rowtype;begin select * into g from public.hotel_access_grants where id=p_grant_id for update;if not found then raise exception using errcode='P0002',message='Acceso inexistente.';end if;if not private.hl_access_permission(g.property_id,'frontdesk.access.open') then raise exception using errcode='42501',message='Tu rol no puede revocar accesos.';end if;update public.hotel_access_grants set status='revoked',revoked_at=now(),revoke_reason=coalesce(nullif(trim(p_reason),''),'manual'),updated_at=now() where id=g.id returning * into g;insert into public.hotel_access_events(property_id,reservation_id,grant_id,access_point_id,event_type,result,source,actor_id,details) values(g.property_id,g.reservation_id,g.id,g.primary_point_id,'pin_revoked','ok','pms',auth.uid(),jsonb_build_object('reason',g.revoke_reason));return g;end$$;
revoke all on function public.hl_access_revoke_grant(uuid,text) from public,anon;grant execute on function public.hl_access_revoke_grant(uuid,text) to authenticated;
create or replace function public.hl_access_create_guest_link(p_reservation_id bigint) returns text language plpgsql security definer set search_path='public','private','pg_temp' as $$declare g public.hotel_access_grants%rowtype;v_property uuid;v_token text;begin select property_id into v_property from public.reservas where id=p_reservation_id;if v_property is null then raise exception using errcode='P0002',message='Reserva inexistente.';end if;if not private.hl_access_permission(v_property,'frontdesk.access.open') then raise exception using errcode='42501',message='Tu rol no puede compartir accesos.';end if;g:=private.hl_access_ensure_grant(p_reservation_id,'precheckin',auth.uid());v_token:=encode(gen_random_bytes(24),'hex');update public.hotel_access_grants set guest_token_hash=digest(v_token,'sha256'),guest_token_created_at=now(),updated_at=now() where id=g.id;insert into public.hotel_access_events(property_id,reservation_id,grant_id,access_point_id,event_type,result,source,actor_id) values(g.property_id,g.reservation_id,g.id,g.primary_point_id,'guest_link_created','ok','pms',auth.uid());return v_token;end$$;
revoke all on function public.hl_access_create_guest_link(bigint) from public,anon;grant execute on function public.hl_access_create_guest_link(bigint) to authenticated;
create or replace function public.hl_access_assisted_entry(p_reservation_id bigint,p_access_point_id uuid) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$declare v_property uuid;v_grant uuid;v_policy public.hotel_access_policies%rowtype;v_point public.hotel_access_points%rowtype;v_ready jsonb;begin select property_id into v_property from public.reservas where id=p_reservation_id;if v_property is null then raise exception using errcode='P0002',message='Reserva inexistente.';end if;if not private.hl_access_permission(v_property,'frontdesk.access.open') then raise exception using errcode='42501',message='Tu rol no puede abrir puertas.';end if;select * into v_policy from public.hotel_access_policies where property_id=v_property;if not coalesce(v_policy.allow_assisted_override,true) then raise exception using errcode='42501',message='La entrada asistida está desactivada.';end if;select * into v_point from public.hotel_access_points where id=p_access_point_id and property_id=v_property and active;if not found then raise exception using errcode='P0002',message='Puerta inexistente o inactiva.';end if;select id into v_grant from public.hotel_access_grants where property_id=v_property and reservation_id=p_reservation_id and status in('prepared','active') order by created_at desc limit 1;v_ready:=private.hl_access_readiness_json(p_reservation_id);insert into public.hotel_access_events(property_id,reservation_id,grant_id,access_point_id,event_type,result,source,actor_id,details) values(v_property,p_reservation_id,v_grant,v_point.id,'assisted_entry_authorized','authorized','reception',auth.uid(),jsonb_build_object('readiness',v_ready,'physical_open',false,'connection_status',v_point.connection_status));return jsonb_build_object('authorized',true,'physical_open',false,'connection_status',v_point.connection_status,'provider',v_point.provider,'readiness',v_ready);end$$;
revoke all on function public.hl_access_assisted_entry(bigint,uuid) from public,anon;grant execute on function public.hl_access_assisted_entry(bigint,uuid) to authenticated;

create or replace function public.hl_access_guest_snapshot(p_token text) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$declare g public.hotel_access_grants%rowtype;r public.reservas%rowtype;h public.habitaciones%rowtype;s public.hotel_os_settings%rowtype;v_ready jsonb;v_points jsonb;begin if p_token is null or length(p_token)<32 then return jsonb_build_object('ok',false,'error','invalid_token');end if;select * into g from public.hotel_access_grants where guest_token_hash=digest(p_token,'sha256') order by guest_token_created_at desc limit 1;if not found then return jsonb_build_object('ok',false,'error','invalid_token');end if;select * into r from public.reservas where id=g.reservation_id and property_id=g.property_id;if not found or g.status='revoked' or lower(coalesce(r.estado,'')) in('cancelada','finalizada') or coalesce(r.no_show,false) or now()>=g.valid_until then return jsonb_build_object('ok',false,'error','access_expired');end if;select * into h from public.habitaciones where id=r.habitacion_id;select * into s from public.hotel_os_settings where property_id=r.property_id;v_ready:=private.hl_access_readiness_json(r.id);select coalesce(jsonb_agg(x.obj order by x.seq,x.name),'[]'::jsonb) into v_points from(select 0 seq,p.name,jsonb_build_object('id',p.id,'name',p.name,'kind',p.kind,'zone',p.zone,'provider',p.provider,'connection_status',p.connection_status,'remote_open_enabled',p.remote_open_enabled,'primary',true)obj from public.hotel_access_points p where p.id=g.primary_point_id and p.active union all select l.sequence+1,p.name,jsonb_build_object('id',p.id,'name',p.name,'kind',p.kind,'zone',p.zone,'provider',p.provider,'connection_status',p.connection_status,'remote_open_enabled',p.remote_open_enabled,'primary',false) from public.hotel_access_links l join public.hotel_access_points p on p.id=l.inherited_point_id and p.active where l.property_id=r.property_id and l.source_point_id=g.primary_point_id and l.active and(p.linked_service_kind is null or exists(select 1 from jsonb_array_elements(coalesce(r.servicios,'[]'::jsonb))svc where lower(coalesce(svc->>'kind',''))=lower(p.linked_service_kind) or lower(coalesce(svc->>'resource_category',''))=lower(p.linked_service_kind))))x;return jsonb_build_object('ok',true,'hotel',jsonb_build_object('name',coalesce(s.hotel_name,'Habitación Llena'),'logo',s.logo_data_url,'welcome',s.welcome_message),'guest',jsonb_build_object('name',r.nombre_huesped),'reservation',jsonb_build_object('id',r.id,'number',r.numero_reserva,'arrival',r.fecha_entrada,'departure',r.fecha_salida,'status',r.estado),'room',jsonb_build_object('id',h.id,'name',h.nombre,'type',h.tipo),'ready',v_ready,'pin_code',case when(v_ready->>'ready')::boolean then g.pin_code else null end,'grant',jsonb_build_object('status',case when(v_ready->>'ready')::boolean then 'active' else 'prepared' end,'valid_from',g.valid_from,'valid_until',g.valid_until),'access_points',v_points);end$$;
revoke all on function public.hl_access_guest_snapshot(text) from public;grant execute on function public.hl_access_guest_snapshot(text) to anon,authenticated;

create or replace function private.hl_access_reservation_lifecycle() returns trigger language plpgsql security definer set search_path='public','private','pg_temp' as $$declare g public.hotel_access_grants%rowtype;v_should boolean;v_ready jsonb;begin if lower(coalesce(new.estado,'')) in('cancelada','finalizada') or coalesce(new.no_show,false) then update public.hotel_access_grants set status='revoked',revoked_at=coalesce(revoked_at,now()),revoke_reason=case when coalesce(new.no_show,false) then 'no_show' else 'checkout' end,updated_at=now() where property_id=new.property_id and reservation_id=new.id and status in('prepared','active');update public.hotel_key_issues set status='revoked',revoked_at=coalesce(revoked_at,now()) where property_id=new.property_id and reserva_id=new.id and status not in('revoked','failed');insert into public.hotel_access_events(property_id,reservation_id,event_type,result,source,details) select new.property_id,new.id,'automatic_revocation','ok','system',jsonb_build_object('reservation_status',new.estado,'no_show',new.no_show) where exists(select 1 from public.hotel_access_grants where property_id=new.property_id and reservation_id=new.id and revoked_at is not null);return new;end if;v_should:=new.habitacion_id is not null and(lower(coalesce(new.estado,''))='alojado' or lower(coalesce(new.web_checkin_status,'')) in('submitted','completed','approved','done','verified','complete'));if v_should and exists(select 1 from public.hotel_access_points where property_id=new.property_id and room_id=new.habitacion_id and kind='room' and active) then begin g:=private.hl_access_ensure_grant(new.id,case when lower(coalesce(new.estado,''))='alojado' then 'checkin' else 'precheckin' end,null);exception when others then null;end;end if;if exists(select 1 from public.hotel_access_grants where property_id=new.property_id and reservation_id=new.id and status in('prepared','active')) then v_ready:=private.hl_access_readiness_json(new.id);update public.hotel_access_grants set status=case when(v_ready->>'ready')::boolean then 'active' else 'prepared' end,conditions_snapshot=v_ready,activated_at=case when(v_ready->>'ready')::boolean then coalesce(activated_at,now()) else activated_at end,updated_at=now() where property_id=new.property_id and reservation_id=new.id and status in('prepared','active');end if;return new;end$$;
drop trigger if exists trg_hl_access_reservation_lifecycle on public.reservas;create trigger trg_hl_access_reservation_lifecycle after insert or update of habitacion_id,estado,no_show,web_checkin_status,fecha_entrada,fecha_salida,hora_llegada_estimada,hora_salida_estimada on public.reservas for each row execute function private.hl_access_reservation_lifecycle();
create or replace function private.hl_access_refresh_from_payment() returns trigger language plpgsql security definer set search_path='public','private','pg_temp' as $$declare v_res bigint;v_ready jsonb;begin v_res:=case when tg_op='DELETE' then old.reserva_id else new.reserva_id end;if exists(select 1 from public.hotel_access_grants where reservation_id=v_res and status in('prepared','active')) then v_ready:=private.hl_access_readiness_json(v_res);update public.hotel_access_grants set status=case when(v_ready->>'ready')::boolean then 'active' else 'prepared' end,conditions_snapshot=v_ready,activated_at=case when(v_ready->>'ready')::boolean then coalesce(activated_at,now()) else activated_at end,updated_at=now() where reservation_id=v_res and status in('prepared','active');end if;if tg_op='DELETE' then return old;end if;return new;end$$;
drop trigger if exists trg_hl_access_payment_refresh on public.pagos;create trigger trg_hl_access_payment_refresh after insert or update or delete on public.pagos for each row execute function private.hl_access_refresh_from_payment();
create or replace function private.hl_access_refresh_from_room() returns trigger language plpgsql security definer set search_path='public','private','pg_temp' as $$declare rec record;v_ready jsonb;begin if old.estado is not distinct from new.estado then return new;end if;for rec in select distinct g.reservation_id from public.hotel_access_grants g join public.reservas r on r.id=g.reservation_id where g.property_id=new.property_id and r.habitacion_id=new.id and g.status in('prepared','active') loop v_ready:=private.hl_access_readiness_json(rec.reservation_id);update public.hotel_access_grants set status=case when(v_ready->>'ready')::boolean then 'active' else 'prepared' end,conditions_snapshot=v_ready,activated_at=case when(v_ready->>'ready')::boolean then coalesce(activated_at,now()) else activated_at end,updated_at=now() where reservation_id=rec.reservation_id and status in('prepared','active');end loop;return new;end$$;
drop trigger if exists trg_hl_access_room_refresh on public.habitaciones;create trigger trg_hl_access_room_refresh after update of estado on public.habitaciones for each row execute function private.hl_access_refresh_from_room();
revoke execute on function private.hl_access_sync_room_point() from public,anon,authenticated;revoke execute on function private.hl_access_reservation_lifecycle() from public,anon,authenticated;revoke execute on function private.hl_access_refresh_from_payment() from public,anon,authenticated;revoke execute on function private.hl_access_refresh_from_room() from public,anon,authenticated;
